Endpoint lifecycle
Dulche.Start(port);
Starts a local Dulche endpoint on the specified port. Local Start requires an explicit port; Start(Remote(...)) instead requires an explicit remote target.

Endpoint configuration
Endpoints can be created and configured as one unit. Example:
Endpoint Laguna = new Endpoint(port) {
    Model = GetModelByID(laguna-xs);
    Context = 19000;
    Timeout = 300;
    ToolCallsAllowed = All;
    // Other supported model/endpoint properties may also be configured here.
};

Subagent Worker = new Subagent {
    ParentRequestID = requestID;
    Prompt = "Perform the delegated work";
    Model = Auto;
    Endpoint = Auto;
    Context = SubagentContext.Inherit;
    Tools = Inherit;
    Permissions = Inherit;
    FailurePolicy = SubagentFailurePolicy.Collect;
    Budget = new SubagentBudget {
        MaxTokens = ...;
        MaxTime = ...;
        MaxSteps = ...;
        MaxToolCalls = ...;
        MaxCost = ...;
    };
    Limits = new SubagentLimits {
        MaxChildren = ...;
        MaxParallelChildren = ...;
        MaxDepth = ...;
    };
};

SubagentHandle Handle = Dulche.Subagent.Start(Worker);
SubagentHandle[] Handles = Dulche.Subagent.StartParallel([WorkerA, WorkerB, WorkerC]);
